import React from 'react';
import { useNavigate } from 'react-router-dom';
import { FaTachometerAlt,  FaCalendarAlt, FaEdit, FaChalkboardTeacher, FaSignOutAlt } from 'react-icons/fa';

const Nav = ({ isSidebarOpen }) => {
  const navigate = useNavigate();

  const handleLogout = () => {
    // Hapus token autentikasi dan role dari localStorage
    localStorage.removeItem('token');
    localStorage.removeItem('role');
    // Redirect ke halaman login
    navigate('/login');
  };

  return (
    <aside className={`w-64 bg-teal-700 text-white flex-shrink-0 transition-all duration-300 ${isSidebarOpen ? 'block' : 'w-[85px]'} p-4`} >
      <nav>
        <ul className="space-y-4">
          <li className="text-xl">
            <a href="/dashboardMahasiswa" className="flex items-center px-4 py-3 rounded-lg hover:bg-teal-600 transition duration-200">
              <FaTachometerAlt className={`inline-block ${isSidebarOpen ? 'mr-3' : ''} text-2xl`} />
              {isSidebarOpen && 'Dashboard'}
            </a>
          </li>
          <li className="text-xl">
            <a href="/pembayaranMahasiswa" className="flex items-center px-4 py-3 rounded-lg hover:bg-teal-600 transition duration-200">
              <FaCalendarAlt className={`inline-block ${isSidebarOpen ? 'mr-3' : ''} text-2xl`} />
              {isSidebarOpen && 'Keuangan'}
            </a>
          </li>
          <li className="text-xl">
            <a href="/jadwalMahasiswa" className="flex items-center px-4 py-3 rounded-lg hover:bg-teal-600 transition duration-200">
              <FaChalkboardTeacher className={`inline-block ${isSidebarOpen ? 'mr-3' : ''} text-2xl`} />
              {isSidebarOpen && 'Jadwal'}
            </a>
          </li>
          <li className="text-xl">
            <a href="/absenMahasiswa" className="flex items-center px-4 py-3 rounded-lg hover:bg-teal-600 transition duration-200">
              <FaEdit className={`inline-block ${isSidebarOpen ? 'mr-3' : ''} text-2xl`} />
              {isSidebarOpen && 'Presensi'}
            </a>
          </li>
          <li className="text-xl">
            <button onClick={handleLogout} className="flex items-center w-full text-left px-4 py-3 rounded-lg hover:bg-red-600 hover:text-white transition duration-200">
              <FaSignOutAlt className={`inline-block ${isSidebarOpen ? 'mr-3' : ''} text-2xl`} />
              {isSidebarOpen && 'Logout'}
            </button>
          </li>
        </ul>
      </nav>
    </aside>
  );
};

export default Nav;
